def links(*ids): return '<br>'.join(f'<a href="{e(S[k][1],quote=True)}">{e(S[k][0])} ↗</a>' for k in ids)
def table(headers,rows,caption=''):
 return '<div class="table-wrap"><table>'+ ('<caption>'+caption+'</caption>' if caption else '')+'<thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
NAV=[('index.html','Overview'),('accounts.html','Accounts'),('returns.html','Returns & FDIC'),('promotions.html','Promotions'),('security.html','Security & opening'),('review.html','Flagged for Review'),('sources.html','Sources')]
def page(file,title,lead,body):
 nav=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+'>'+t+'</a>' for f,t in NAV)
 (OUT/file).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Official-source savings account research, dated October 22, 2026. Returns are scenarios, not guarantees."><title>{e(title)} · Savings Brief</title><link rel="stylesheet" href="style.css"><script src="filter.js" defer></script></head><body><a href="#main" class="small">Skip to content</a><header><a class="brand" href="index.html"><span>◈</span> Savings Brief</a><nav aria-label="Main">{nav}</nav></header><main id="main"><div class="eyebrow">Research snapshot / 22 October 2026</div><h1>{title}</h1><p class="lead">{lead}</p>{body}</main><footer>Official-source research · USD · New York planning context · Checked October 22, 2026, not a live rate feed.<br>Independent comparison; no affiliate links. Illustrations are pre-tax and not a promise of future returns. No account has been opened.</footer></body></html>')
